import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.BGlkWkwp.js";const f=JSON.parse('{"title":"ColorPicker","description":"","frontmatter":{},"headers":[],"relativePath":"components/color-picker.md","filePath":"components/color-picker.md"}'),d={name:"components/color-picker.md"};function c(s,e,i,l,h,n){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="colorpicker" tabindex="-1">ColorPicker <a class="header-anchor" href="#colorpicker" aria-label="Permalink to &quot;ColorPicker&quot;">​</a></h1><p>ColorPicker is a board to pick one color.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it to choose a color for something drawn. In the flow of a page or a panel, the board draws its own surface and line; inside a surface that already draws them, such as a <a href="./popover">Popover</a>, pass <code>bare</code>. A small set of named colors alone is a <a href="./color-grid">ColorGrid</a>. The fields show the value as hex, RGB or HSL, starting with <code>format</code>. The names of the parts come from the <a href="./README#messages">messages</a> (<code>color</code>, <code>close</code>, <code>hue</code>, <code>saturation</code>, <code>lightness</code>, <code>saturationValue</code>, <code>saturationValueText</code>, <code>eyedropper</code>, <code>colorCode</code>, and the names of the default colors).</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>#E5484D</code></td><td>The chosen color as #RRGGBB (bindable)</td></tr><tr><td><code>swatches</code></td><td>nine colors</td><td>The preset colors, <code>{ name, hex }[]</code></td></tr><tr><td><code>format</code></td><td><code>hex</code></td><td>The format the fields start in: <code>hex</code>, <code>rgb</code> or <code>hsl</code></td></tr><tr><td><code>bare</code></td><td><code>false</code></td><td>Keeps only its padding, for a slot with a surface</td></tr><tr><td><code>title</code></td><td>the <code>color</code> message</td><td>The title</td></tr><tr><td><code>onpick</code></td><td></td><td>Called with the color and its name (the hex without one)</td></tr><tr><td><code>onclose</code></td><td></td><td>Called by the close button</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The board is 15rem wide and never wider than its container, with pad-md inside. It stacks, gap-sm apart, the title (h2) and a close button, a <a href="./color-grid">ColorGrid</a>, the plane of saturation and value, the strip of hues with an eyedropper, and the fields with a <a href="./select">Select</a> of the format. The plane and the strip follow the pointer and the arrow keys; their knobs are the square of an icon with two edges, so they show on any color. The eyedropper works where the browser has the EyeDropper API. An invalid hex code is turned back to the current color.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/color-picker/" title="ColorPicker" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/color-picker/" target="_blank" rel="noopener">ColorPicker</a></figcaption></figure>',10)])])}const m=o(d,[["render",c]]);export{f as __pageData,m as default};
